import{_ as d,o as a,c as r,a3 as e}from"./chunks/framework.D81Tvp8W.js";const g=JSON.parse('{"title":"关系型数据库（RDBMS）指南","description":"","frontmatter":{"title":"关系型数据库（RDBMS）指南","date":"2025-09-02T00:00:00.000Z","categories":["backend","RDBMS"],"tags":["后端","RDBMS"]},"headers":[],"relativePath":"backend/RDBMS/index.md","filePath":"backend/RDBMS/index.md","lastUpdated":1786872962000}'),s={name:"backend/RDBMS/index.md"};function n(o,t,l,i,h,c){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="🗄️-关系型数据库-rdbms-指南" tabindex="-1">🗄️ 关系型数据库（RDBMS）指南 <a class="header-anchor" href="#🗄️-关系型数据库-rdbms-指南" aria-label="Permalink to &quot;🗄️ 关系型数据库（RDBMS）指南&quot;">​</a></h1><p>关系型数据库是数据存储的&quot;老大哥&quot;，支撑着从银行系统到电商平台的绝大多数业务。本文介绍 RDBMS 的核心概念，以及主流数据库 MySQL 与 PostgreSQL 的选型。</p><hr><h2 id="🧠-一、什么是关系型数据库" tabindex="-1">🧠 一、什么是关系型数据库？ <a class="header-anchor" href="#🧠-一、什么是关系型数据库" aria-label="Permalink to &quot;🧠 一、什么是关系型数据库？&quot;">​</a></h2><p>关系型数据库（Relational Database Management System，RDBMS）基于 <strong>关系模型</strong>，数据组织成 <strong>表（Table）</strong>，表由 <strong>行（Row）</strong> 和 <strong>列（Column）</strong> 组成，表之间通过 <strong>主键/外键</strong> 建立关联。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学生表 student                    成绩表 score</span></span>
<span class="line"><span>┌────┬──────┬────┐              ┌────────┬───────┐</span></span>
<span class="line"><span>│ id │ name │ age│              │ stu_id │ score │</span></span>
<span class="line"><span>├────┼──────┼────┤              ├────────┼───────┤</span></span>
<span class="line"><span>│ 1  │ 张三 │ 18 │              │ 1      │ 95    │</span></span>
<span class="line"><span>│ 2  │ 李四 │ 19 │              │ 1      │ 88    │</span></span>
<span class="line"><span>└────┴──────┴────┘              │ 2      │ 90    │</span></span>
<span class="line"><span>  主键 id ──────────────────→   └────────┴───────┘</span></span>
<span class="line"><span>                               外键 stu_id 引用 student.id</span></span></code></pre></div><hr><h2 id="🔑-二、核心概念" tabindex="-1">🔑 二、核心概念 <a class="header-anchor" href="#🔑-二、核心概念" aria-label="Permalink to &quot;🔑 二、核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>表（Table）</strong></td><td>数据的容器，由行和列组成</td></tr><tr><td><strong>行（Row / Record）</strong></td><td>一条记录</td></tr><tr><td><strong>列（Column / Field）</strong></td><td>一个字段</td></tr><tr><td><strong>主键（Primary Key）</strong></td><td>唯一标识一行的列，不可为空</td></tr><tr><td><strong>外键（Foreign Key）</strong></td><td>引用其他表主键的列，建立关联</td></tr><tr><td><strong>索引（Index）</strong></td><td>加速查询的数据结构（如 B+ 树）</td></tr><tr><td><strong>事务（Transaction）</strong></td><td>一组要么全成功、要么全回滚的操作</td></tr></tbody></table><p><strong>SQL（Structured Query Language）</strong> 是与 RDBMS 交互的标准语言，四大类：</p><table tabindex="0"><thead><tr><th>类别</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>DDL</td><td>定义表结构</td><td><code>CREATE TABLE</code>、<code>ALTER</code></td></tr><tr><td>DML</td><td>增删改数据</td><td><code>INSERT</code>、<code>UPDATE</code>、<code>DELETE</code></td></tr><tr><td>DQL</td><td>查询数据</td><td><code>SELECT</code></td></tr><tr><td>DCL</td><td>权限控制</td><td><code>GRANT</code>、<code>REVOKE</code></td></tr></tbody></table><hr><h2 id="⚖️-三、rdbms-与-nosql-对比" tabindex="-1">⚖️ 三、RDBMS 与 NoSQL 对比 <a class="header-anchor" href="#⚖️-三、rdbms-与-nosql-对比" aria-label="Permalink to &quot;⚖️ 三、RDBMS 与 NoSQL 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>RDBMS（MySQL/PostgreSQL）</th><th>NoSQL（MongoDB/Redis）</th></tr></thead><tbody><tr><td>数据模型</td><td>二维表，强结构</td><td>文档/键值/列族/图</td></tr><tr><td>Schema</td><td>固定，需预先定义</td><td>灵活，动态</td></tr><tr><td>事务</td><td>强 ACID</td><td>弱（最终一致）</td></tr><tr><td>扩展方式</td><td>垂直为主（主从/分库分表）</td><td>水平扩展天然支持</td></tr><tr><td>查询</td><td>SQL 标准</td><td>各自方言</td></tr><tr><td>适用</td><td>强一致性业务（订单、账务）</td><td>海量数据、高并发、灵活结构</td></tr></tbody></table><blockquote><p>💡 实践：核心业务数据用 RDBMS 保证一致性，缓存/日志/灵活结构用 NoSQL。</p></blockquote><hr><h2 id="🔀-四、mysql-vs-postgresql" tabindex="-1">🔀 四、MySQL vs PostgreSQL <a class="header-anchor" href="#🔀-四、mysql-vs-postgresql" aria-label="Permalink to &quot;🔀 四、MySQL vs PostgreSQL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>MySQL</th><th>PostgreSQL</th></tr></thead><tbody><tr><td>定位</td><td>轻量、高性能、易用</td><td>功能全面、标准兼容、扩展性强</td></tr><tr><td>性能</td><td>简单查询读性能好</td><td>复杂查询/大数据量更强</td></tr><tr><td>数据类型</td><td>基础类型</td><td>JSONB、数组、区间、全文检索等丰富</td></tr><tr><td>扩展</td><td>分区表、复制</td><td>CTE、窗口函数、物化视图、插件（PostGIS）</td></tr><tr><td>生态</td><td>使用最广、文档最多</td><td>功能前沿、被&quot;用 PG 解决一切&quot;喜爱</td></tr><tr><td>选择</td><td>中小型应用、Web 常用</td><td>复杂查询、GIS、需要高级特性</td></tr></tbody></table><p><strong>入门学习</strong>：</p><ul><li><a href="./MySQL从入门到放弃.html">MySQL 从入门到放弃</a></li><li><a href="./PostgreSQL从入门到放弃.html">PostgreSQL 从入门到放弃</a></li></ul><hr><h2 id="🗺️-五、学习路线" tabindex="-1">🗺️ 五、学习路线 <a class="header-anchor" href="#🗺️-五、学习路线" aria-label="Permalink to &quot;🗺️ 五、学习路线&quot;">​</a></h2><ol><li><strong>SQL 基础</strong>：增删改查、聚合、JOIN</li><li><strong>设计</strong>：建表规范、范式、索引设计</li><li><strong>进阶</strong>：事务与隔离级别、锁、执行计划</li><li><strong>高可用</strong>：主从复制、读写分离、分库分表</li><li><strong>实践</strong>：配合后端框架（MyBatis / JPA / Prisma）使用</li></ol><hr><h2 id="🎯-六、小结" tabindex="-1">🎯 六、小结 <a class="header-anchor" href="#🎯-六、小结" aria-label="Permalink to &quot;🎯 六、小结&quot;">​</a></h2><ul><li>RDBMS 用&quot;表 + 关系&quot;组织数据，SQL 是通用查询语言</li><li>核心特性：主键外键、索引、ACID 事务</li><li>MySQL 与 PostgreSQL 各有优势，按业务场景选择</li><li>一致性敏感的业务数据首选 RDBMS</li></ul><hr>`,27)])])}const S=d(s,[["render",n]]);export{g as __pageData,S as default};
